import json
import datetime
import re
vars['next'] = 'speak'
vars['instruction'] = 'Say you do not have that information. Ask whether the customer wants help from a person.'
s = {}
prefix = ''
turn_defaults = {'turn_intent': 'other', 'turn_decision': 'none', 'turn_amount': '', 'turn_amount_reference': 'none', 'turn_full_unaffordable': 'no', 'turn_date': '', 'turn_answer': '', 'turn_numeric_dob': '', 'turn_time': '', 'turn_question': 'none', 'turn_hardship': 'no', 'turn_human': 'no', 'turn_no_talk': 'no', 'turn_plan': 'no', 'turn_caller': 'unknown', 'turn_callback_date': '', 'turn_callback_time': ''}
try:
    raw = vars.get('call_state', '')
    s = json.loads(raw) if isinstance(raw, str) and raw else (raw if isinstance(raw, dict) else {})
    now = datetime.datetime.fromisoformat(str(vars.get('now')))
    today = now.date()
    holidays = {'2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'}
    def business(d):
        return d.weekday() < 5 and d.isoformat() not in holidays
    def forward(d):
        while not business(d):
            d += datetime.timedelta(days=1)
        return d
    def after(d, n):
        while n:
            d += datetime.timedelta(days=1)
            if business(d):
                n -= 1
        return d
    def last_business_week(d):
        end = d - datetime.timedelta(days=d.weekday()) + datetime.timedelta(days=4)
        while not business(end):
            end -= datetime.timedelta(days=1)
        return end
    def truth(v):
        return str(v).lower() == 'true'
    def number(v):
        x = float(str(v).replace(',', '').strip())
        if x != x or x in (float('inf'), float('-inf')):
            raise ValueError('invalid amount')
        return x
    def date_value(text):
        t = re.sub(r'^on\s+', '', str(text).strip().lower().rstrip('.!?'))
        if not t or t == 'vague':
            return ''
        if t == 'today':
            return today.isoformat()
        if t == 'tomorrow':
            return (today + datetime.timedelta(days=1)).isoformat()
        names = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
        bits = t.split()
        if len(bits) == 2 and bits[0] in ('this', 'next') and bits[1] in names:
            monday = today - datetime.timedelta(days=today.weekday())
            offset = names.index(bits[1]) + (7 if bits[0] == 'next' else 0)
            return (monday + datetime.timedelta(days=offset)).isoformat()
        if t in names:
            return (today + datetime.timedelta(days=(names.index(t) - today.weekday()) % 7)).isoformat()
        t = re.sub(r'^on\s+', '', t).strip().rstrip('.!?')
        weekday = None
        for i, name in enumerate(names):
            if re.search(r'\b' + name + r'\b', t):
                if weekday is not None:
                    raise ValueError('conflicting weekdays')
                weekday = i
                t = re.sub(r'\b' + name + r'\b', ' ', t).strip(' ,')
        def checked(d):
            if weekday is not None and d.weekday() != weekday:
                raise ValueError('weekday and calendar date disagree')
            return d.isoformat()
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', t):
            return checked(datetime.date.fromisoformat(t))
        numeric = re.fullmatch(r'(\d{1,2})[/-](\d{1,2})[/-](\d{4})', t)
        if numeric:
            a, b, year = [int(x) for x in numeric.groups()]
            possibilities = set()
            for day_num, month_num in ((a, b), (b, a)):
                try:
                    d = datetime.date(year, month_num, day_num)
                    if weekday is None or d.weekday() == weekday:
                        possibilities.add(d)
                except ValueError:
                    pass
            if len(possibilities) != 1:
                raise ValueError('ambiguous numeric date; ask for month word')
            return checked(next(iter(possibilities)))
        t = re.sub(r'(?<=\d)(st|nd|rd|th)\b', '', t)
        t = re.sub(r'\b(on|the|of)\b', ' ', t)
        tokens = t.replace(',', ' ').replace('-', ' ').split()
        units = dict(zip('one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen'.split(), range(1, 20)))
        ordinals = dict(zip('first second third fourth fifth sixth seventh eighth ninth tenth eleventh twelfth thirteenth fourteenth fifteenth sixteenth seventeenth eighteenth nineteenth'.split(), range(1, 20)))
        def day_at(words):
            if not words:
                raise ValueError('missing day')
            w = words[0]
            if w.isdigit() and 1 <= int(w) <= 31:
                return int(w), 1
            if w in units or w in ordinals:
                return units.get(w, ordinals.get(w)), 1
            if w in ('twentieth', 'thirtieth'):
                return (20 if w == 'twentieth' else 30), 1
            if w in ('twenty', 'thirty'):
                n = 20 if w == 'twenty' else 30
                if len(words) > 1:
                    v = units.get(words[1], ordinals.get(words[1], 0))
                    if 1 <= v <= 9 and n + v <= 31:
                        return n + v, 2
                return n, 1
            raise ValueError('unreadable day')
        def year_value(words):
            words = [w for w in words if w != 'and']
            if len(words) == 1 and re.fullmatch(r'\d{4}', words[0]):
                return int(words[0])
            if words[:2] == ['two', 'thousand']:
                base, words = 2000, words[2:]
            elif words[:1] in (['nineteen'], ['twenty']):
                base, words = (1900 if words[0] == 'nineteen' else 2000), words[1:]
            else:
                raise ValueError('unreadable explicit year')
            if not words:
                return base
            tens = dict(zip('twenty thirty forty fifty sixty seventy eighty ninety'.split(), range(20, 100, 10)))
            if len(words) == 1 and words[0] in units:
                return base + units[words[0]]
            if words[0] in tens and len(words) <= 2:
                tail = 0 if len(words) == 1 else units.get(words[1], 100)
                if tail < 10:
                    return base + tens[words[0]] + tail
            raise ValueError('unreadable explicit year')
        months = 'january february march april may june july august september october november december'.split()
        aliases = {name: i + 1 for i, name in enumerate(months)}
        aliases.update({name[:3]: i + 1 for i, name in enumerate(months)})
        aliases['sept'] = 9
        positions = [i for i, w in enumerate(tokens) if w in aliases]
        if len(positions) > 1:
            raise ValueError('conflicting months')
        month = None
        year_words = []
        if positions:
            pos = positions[0]
            month = aliases[tokens[pos]]
            if pos == 0:
                day_num, used = day_at(tokens[1:])
                year_words = tokens[1 + used:]
            else:
                day_num, used = day_at(tokens[:pos])
                if used != pos:
                    raise ValueError('unresolved date words')
                year_words = tokens[pos + 1:]
        else:
            day_num, used = day_at(tokens)
            if used != len(tokens):
                raise ValueError('missing month or unresolved date words')
        if month is not None:
            year = year_value(year_words) if year_words else today.year
            d = datetime.date(year, month, day_num)
            if not year_words and d < today:
                d = datetime.date(year + 1, month, day_num)
            return checked(d)
        # Resolve the nearest upcoming day in this or next month only.
        # A weekday mismatch requires clarification, not a distant-month search.
        for offset in (0, 1):
            month_index = today.year * 12 + today.month - 1 + offset
            year, month_zero = divmod(month_index, 12)
            try:
                d = datetime.date(year, month_zero + 1, day_num)
            except ValueError:
                continue
            if d >= today:
                return checked(d)
        raise ValueError('ambiguous omitted month; ask for exact date')
    def current_product():
        return s.get('products', {}).get(s.get('product_id', ''), {})
    def tell(stage, text):
        s['stage'] = stage
        s['prompt'] = text
        vars['next'] = 'speak'
    def request(kind):
        s['pending'] = kind
        vars['api_data'] = '{}'
        vars['next'] = kind
    def finish(outcome, reason='', message=''):
        p = current_product()
        if s.get('transfer_success'):
            outcome = 'transferred'
            reason = s['transfer_reason']
        elif p.get('recorded'):
            outcome = 'promise'
            reason = ''
        pairs = {'promise': [''], 'paid': [''], 'transferred': ['restructuring', 'human', 'support'], 'no_promise': ['refused', 'hardship', 'dispute', 'service_error'], 'not_verified': ['failed', 'declined'], 'not_reached': ['callback', 'no_callback', 'wrong_number', 'deceased', 'unclear']}
        if outcome not in pairs or reason not in pairs[outcome]:
            tell(s.get('stage', 'locate'), 'Say you do not have that information. Ask whether a person can help.')
            return
        vars['outcome'] = outcome
        vars['reason'] = reason
        vars['closing_message'] = (prefix + message + ' Thank you. Goodbye.').strip()
        s['terminal_selected'] = True
        vars['next'] = 'goodbye'
    def transfer(queue):
        s['transfer_queue'] = queue
        s['requested_transfer_reason'] = {'general': 'human', 'support': 'support', 'restructuring': 'restructuring'}[queue]
        vars['transfer_queue'] = queue
        request('transfer')
    def support():
        tell('support', 'Offer: Would you like me to connect you with our customer support team? Do not make a persuasion attempt.')
    def valid_candidate(p):
        try:
            d = datetime.date.fromisoformat(p.get('date', ''))
            a = number(p.get('amount', ''))
            return s.get('verified') is True and s.get('caller_status') != 'third_party' and not p.get('recorded') and not p.get('terms_unresolved', False) and p['floor'] <= a <= p['past_due'] and today <= d <= datetime.date.fromisoformat(p['deadline']) and business(d)
        except Exception:
            return False
    def pair(a, d):
        return str(number(a)) + '|' + str(d)
    def offer(p, amount, day, explanation=''):
        p['confirmed'] = ''
        p['readback'] = ''
        p['terms_unresolved'] = False
        p['amount'] = number(amount)
        p['date'] = str(day)
        tell('negotiate', explanation + ' Offer exactly ' + str(p['amount']) + ' for ' + p['label'] + ' on ' + p['date'] + '. Ask whether the customer can make that payment. Do not ask how much they can pay. Do not independently substitute different terms.')
    def readback(p):
        p['confirmed'] = ''
        p['readback'] = pair(p['amount'], p['date'])
        tell('confirm', 'Read back exactly this product, amount, and date: ' + p['label'] + ', ' + str(p['amount']) + ', ' + p['date'] + '. Say all three values aloud in this turn, even if the customer just repeated the date or previously accepted the amount. Then ask exactly: Do you confirm? A date-only paraphrase or Does that work for you? is not a readback. Answer any genuine secondary question briefly without replacing this complete readback. Wait for a fresh clear yes. Do not claim this is recorded. Do not substitute any other amount or date from history.')
    def persuade(p):
        p['confirmed'] = ''
        p['readback'] = ''
        if s.get('hardship'):
            support()
            return
        rejected = pair(p['amount'], p['date'])
        if rejected not in p['refused_offers']:
            p['refused_offers'].append(rejected)
        while p['attempts'] < p['budget']:
            p['attempts'] += 1
            if p['attempts'] == 1:
                amount = p['floor'] if p['full_too_much'] else p['past_due']
                d = last_business_week(today)
                if d == today:
                    d = last_business_week(today + datetime.timedelta(days=7))
                day = d.isoformat()
            else:
                amount = p['floor']
                day = p['deadline']
            if pair(amount, day) not in p['refused_offers']:
                date_only = p['attempts'] == 1 and p['floor_offered'] and number(amount) == number(p['amount']) == number(p['floor']) and day != p['date']
                explanation = 'The rest stays overdue.' if amount < p['past_due'] and not date_only else ''
                offer(p, amount, day, explanation)
                if date_only:
                    tell('negotiate', 'Refer to the payment already offered without restating its unchanged amount or repeating the rest-stays-overdue explanation. Ask whether the customer can make that payment on ' + day + '. This advances the persuasion date, not a second floor offer. Do not ask how much they can pay. A subsequent final confirmation must still read back the product, amount and date in full.')
                return
        finish('no_promise', 'refused')
    def callback_turn(day, time_text, decision, intent, newly_third_party=False):
        if (decision == 'reject' or intent in ('reject', 'done', 'no_talk')) and not day and not time_text and not newly_third_party:
            finish('not_reached', 'no_callback')
            return
        if day:
            s['callback_proposed_date'] = day
        if time_text:
            s['callback_proposed_time'] = time_text
        proposed_day = str(s.get('callback_proposed_date', ''))
        proposed_time = str(s.get('callback_proposed_time', ''))
        if not day and not time_text and not proposed_day and not proposed_time:
            tell('callback', 'Ask when ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + ' can be reached. Do not repeat name identification. Disclose nothing beyond the opening identification of Freya Bank and recording notice. Do not ask this person security questions or discuss an offer to pay.')
            return
        invalid = False
        d = ''
        t = ''
        try:
            if proposed_day:
                d = date_value(proposed_day)
                invalid = not d or d not in (today.isoformat(), after(today, 1).isoformat())
            if proposed_time:
                t = datetime.time.fromisoformat(proposed_time)
                invalid = invalid or not (datetime.time(10, 0) <= t <= datetime.time(19, 0))
            if d and t and not invalid:
                stamp = datetime.datetime.combine(datetime.date.fromisoformat(d), t)
                if now.tzinfo:
                    stamp = stamp.replace(tzinfo=now.tzinfo)
                invalid = stamp <= now
        except Exception:
            invalid = True
        if invalid:
            s['callback_invalid'] += 1
            s['callback_proposed_date'] = ''
            s['callback_proposed_time'] = ''
            if s['callback_invalid'] >= 2:
                finish('not_reached', 'no_callback')
            else:
                tell('callback', 'Ask once for another callback date and time. It must be today or ' + after(today, 1).isoformat() + ', from 10:00 to 19:00 inclusive, and later than ' + str(vars.get('now')) + '. Do not schedule an invalid time. Do not disclose the purpose or ask security questions.')
        elif not proposed_day:
            tell('callback', 'The offered time is ' + proposed_time + '. Ask only which day the customer can be reached at that time: today or ' + after(today, 1).isoformat() + '. Do not invent a day or repeat the time question. Do not disclose the purpose.')
        elif not proposed_time:
            tell('callback', 'The offered day is ' + d + '. Ask only what time the customer can be reached that day, between 10:00 and 19:00 and later than the supplied current time. Do not invent a time or repeat the day question. Do not disclose the purpose.')
        else:
            vars['callback_date'] = d
            vars['callback_time'] = t.strftime('%H:%M')
            request('callback')
    def candidate(p, amount_text='', date_text='', too_much=False):
        p['confirmed'] = ''
        p['readback'] = ''
        if p.get('terms_unresolved') and not amount_text and not date_text and not too_much:
            tell('negotiate', 'Ask the customer to clarify the unresolved proposed term. A yes alone cannot resolve conflicting or unreadable terms. Do not invent an amount or date.')
            return
        p['terms_unresolved'] = False
        amount = p['amount']
        day = p['date']
        correction = ''
        if too_much:
            p['full_too_much'] = True
            if p['floor_offered']:
                persuade(p)
                return
            p['floor_offered'] = True
            amount = p['floor']
            correction += 'Offer the floor once and say the rest stays overdue. '
        elif amount_text:
            try:
                amount = number(amount_text)
            except Exception:
                p['terms_unresolved'] = True
                tell('negotiate', 'Ask the customer to clarify the conflicting or unreadable amount they just proposed. Do not assume the previous amount still applies. Do not ask an open-ended affordability question.')
                return
            if amount < p['floor']:
                if p['floor_offered']:
                    persuade(p)
                    return
                p['floor_offered'] = True
                amount = p['floor']
                correction += 'Say that the proposed amount cannot be recorded. Offer the floor once and explain that the rest stays overdue. '
            elif amount > p['past_due']:
                amount = p['past_due']
                correction += 'Only propose the full past-due amount, not the higher amount. '
        if date_text and re.search(r'\b(next week|week after next|end of (the )?month|salary|payday|sometime|soon)\b', date_text.lower()) and not re.search(r'\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b', date_text.lower()):
            date_text = 'vague'
        if date_text == 'vague':
            p['amount'] = amount
            if not p.get('need_exact'):
                p['need_exact'] = True
                tell('negotiate', correction + 'Ask once for the exact day of the proposed payment. Do not infer a day from a vague period.')
                return
            date_text = p['deadline']
            correction += 'No exact day was supplied after clarification; propose the deadline. '
        elif p.get('need_exact') and not date_text:
            date_text = p['deadline']
            correction += 'No exact day was supplied after clarification; propose the deadline. '
        if date_text:
            try:
                day = date_value(date_text)
                if not day:
                    raise ValueError('missing day')
                p['need_exact'] = False
            except Exception:
                p['amount'] = amount
                p['terms_unresolved'] = True
                tell('negotiate', 'Ask which exact calendar day the customer is positively proposing. The date is unresolved or conflicting. Do not use a rejected date or invent a date. Do not read back the old date as agreed.')
                return
        d = datetime.date.fromisoformat(day)
        deadline = datetime.date.fromisoformat(p['deadline'])
        if d > deadline:
            day = p['deadline']
            correction += 'Say the latest date you can record is ' + day + ' and offer it. '
        elif d < today:
            day = forward(today).isoformat()
            correction += 'Say that a past date cannot be recorded and offer ' + day + '. '
        elif not business(d):
            day = forward(d).isoformat()
            if day > p['deadline']:
                day = p['deadline']
                correction += 'Say the latest date you can record is ' + day + ' and offer it. '
            else:
                correction += 'Offer the next business day, ' + day + ', instead of the weekend or holiday. '
        p['amount'] = amount
        p['date'] = day
        if not valid_candidate(p):
            tell('negotiate', 'Say this proposal cannot be recorded. Ask for an exact eligible date; offer the deadline ' + p['deadline'] + ' if needed. Do not invent terms.')
        elif correction:
            if pair(amount, day) in p['refused_offers']:
                persuade(p)
            else:
                offer(p, amount, day, correction)
        else:
            readback(p)
    def create(p):
        key = pair(p['amount'], p['date'])
        if valid_candidate(p) and p.get('confirmed') == key and p.get('readback') == key and p.get('create_attempts', 0) < 2:
            p['create_attempts'] += 1
            vars['promise_product_id'] = s['product_id']
            vars['promise_amount'] = p['amount']
            vars['promise_date'] = p['date']
            request('create')
        else:
            p['confirmed'] = ''
            if p.get('recorded'):
                tell('recorded', 'Say an existing recorded promise cannot be changed or cancelled during this call and can be changed in the mobile app.')
            else:
                candidate(p)
    if not s:
        s = {'stage': 'locate', 'name_asks': 1, 'verified': False, 'dob_pass': False, 'wrong': 0, 'security_declines': 0, 'talk_declines': 0, 'callback_invalid': 0, 'human_offered': False, 'human_pending': False, 'hardship': False, 'products': {}, 'pending': '', 'terminal_selected': False, 'carry_prefix': '', 'caller_status': 'unknown', 'callback_proposed_date': '', 'callback_proposed_time': ''}
        tell('locate', 'Your first sentence must be exactly: I am a digital assistant calling from Freya Bank, and we are recording this call. Then ask exactly: Am I speaking with ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + '? Do not disclose the purpose of this call.')
    elif s.get('terminal_selected'):
        vars['next'] = 'goodbye'
    elif s.get('pending'):
        kind = s['pending']
        s['pending'] = ''
        prefix = str(s.get('carry_prefix', ''))
        s['carry_prefix'] = ''
        data = vars.get('api_data', {})
