            if data.get('hint') == 'day_month_swapped':
                tell('security', 'Ask the customer to say their date of birth with the month as a word. This hinted retry does not count as a wrong answer.')
            elif not ok:
                tell('security', 'Say the answer could not be checked. Ask for the same security answer again, using the month as a word for a birth date. Do not count this as a wrong answer or a successful check.')
            elif truth(data.get('verified', False)):
                if s['security_field'] == 'date_of_birth':
                    s['dob_pass'] = True
                    s['security_field'] = 'phone_last4'
                    tell('security', 'Ask only for the last four digits of the phone number on file.')
