                    s['verified'] = True
                    request('account')
                else:
                    tell('security', 'Say identity verification is not complete. Ask again for the last four digits of the phone number on file; do not reveal the account.')
            else:
                s['wrong'] += 1
                if 'wrong_answers_left' in data:
                    try:
                        s['wrong'] = max(s['wrong'], 3 - int(data['wrong_answers_left']))
                    except Exception:
                        pass
                if s['wrong'] >= 3:
                    finish('not_verified', 'failed', 'Please use the mobile app or visit a branch.')
                else:
                    question = 'date of birth' if s['security_field'] == 'date_of_birth' else 'last four digits of the phone number on file'
                    tell('security', 'Say the answer did not match and ask again for the ' + question + '. Do not ask the next security question yet.')
        elif kind == 'account':
            products = data.get('products', [])
            if isinstance(products, str):
                try:
                    products = json.loads(products)
                except Exception:
                    products = []
            usable = ok and s.get('verified') is True and s.get('caller_status') != 'third_party' and isinstance(products, list) and len(products) == 1
            if usable:
                a = products[0]
                usable = isinstance(a, dict) and a.get('type') in ('credit_card', 'personal_loan', 'car_loan') and 1 <= int(a.get('days_late', 0)) <= 45 and bool(a.get('product_id'))
            if usable:
                floor = number(a['minimum_payment'] if a['type'] == 'credit_card' else a['instalment_amount'])
                full = number(a['past_due'])
                usable = 0 < floor <= full and (a['type'] != 'credit_card' or bool(a.get('card_last4')))
            if not usable:
                s['retry_kind'] = 'account'
                tell('service_wait', 'Say account information is not available, without inventing it. Ask whether to try again. A request for a person remains available.')
            else:
                early = int(a['days_late']) <= 7
                label = 'credit card ending ' + str(a.get('card_last4', '')) if a['type'] == 'credit_card' else a['type'].replace('_', ' ')
                pid = str(a['product_id'])
                p = {'product_id': pid, 'type': a['type'], 'card_last4': str(a.get('card_last4', '')), 'label': label, 'past_due': full, 'floor': floor, 'days_late': int(a['days_late']), 'deadline': after(today, 12 if early else 7).isoformat(), 'budget': 1 if early else 2, 'attempts': 0, 'floor_offered': False, 'full_too_much': False, 'amount': full, 'date': today.isoformat(), 'recorded': False, 'confirmed': '', 'readback': '', 'create_attempts': 0, 'refused_offers': [], 'need_exact': False, 'terms_unresolved': False}
                s['products'][pid] = p
                s['product_id'] = pid
                tell('negotiate', 'Say you are calling from the collections team about a late payment. Name the product as ' + label + '. State the full past-due amount ' + str(full) + ' and that it is ' + str(p['days_late']) + ' days late. Ask for that full amount first with exactly: Can you make this payment today?')
        elif kind == 'callback':
            if ok:
                s['callback_recorded'] = True
                finish('not_reached', 'callback', 'The callback has been scheduled.')
            else:
                s['retry_kind'] = 'callback'
                tell('service_wait', 'Say the callback could not be scheduled. Ask whether to try again. Do not say it was scheduled or disclose the call purpose.')
        elif kind == 'transfer':
            if ok:
                s['transfer_success'] = True
                s['transfer_reason'] = s['requested_transfer_reason']
                finish('transferred', s['transfer_reason'], 'I am connecting you with the requested team.')
            else:
                s['retry_kind'] = 'transfer'
                tell('service_wait', 'Say the transfer did not succeed. Ask whether to try again; do not claim anyone has been connected.')
        elif kind == 'create':
            p = current_product()
            if ok:
                p['recorded'] = True
                p['promise_id'] = str(data.get('promise_id', ''))
                tell('recorded', 'Say the promise is recorded. Then say exactly: You will receive a text message confirming this promise. Ask briefly whether the customer has any other question. Never create another promise for this product, change it, or cancel it. A subsequent successful transfer takes precedence in the closing outcome.')
            elif p.get('create_attempts', 0) < 2:
                create(p)
            else:
                finish('no_promise', 'service_error', 'I could not record your promise.')
    else:
        intent = str(vars.get('turn_intent', 'other'))
        decision = str(vars.get('turn_decision', 'none')).strip().lower()
        if decision not in ('accept', 'reject', 'none', 'unclear'):
            decision = 'none'
        amount = str(vars.get('turn_amount', '')).strip()
        amount_reference = str(vars.get('turn_amount_reference', 'none')).strip().lower()
        full_unaffordable = str(vars.get('turn_full_unaffordable', 'no')) == 'yes'
        day = str(vars.get('turn_date', '')).strip().lower()
        answer = str(vars.get('turn_answer', '')).strip()
        numeric_dob = str(vars.get('turn_numeric_dob', '')).strip()
        time_text = str(vars.get('turn_time', '')).strip()
        question = str(vars.get('turn_question', 'none'))
        hardship_new = str(vars.get('turn_hardship', 'no')) == 'yes'
        human = str(vars.get('turn_human', 'no')) == 'yes' or intent == 'human'
        no_talk = str(vars.get('turn_no_talk', 'no')) == 'yes' or intent == 'no_talk'
        plan_request = str(vars.get('turn_plan', 'no')) == 'yes'
        caller = str(vars.get('turn_caller', 'unknown'))
        callback_day = str(vars.get('turn_callback_date', '')).strip().lower()
        callback_time = str(vars.get('turn_callback_time', '')).strip()
        stage = s['stage']
        p = current_product()
        newly_third_party = False
        if caller == 'third_party' or intent == 'third_party':
            newly_third_party = s.get('caller_status') != 'third_party'
            s['caller_status'] = 'third_party'
            if newly_third_party:
                s['human_pending'] = False
                s['callback_proposed_date'] = ''
                s['callback_proposed_time'] = ''
            if stage != 'service_wait':
                stage = 'callback'
                s['stage'] = stage
        elif caller == 'customer_takeover' and s.get('caller_status') == 'third_party':
            s['caller_status'] = 'unknown'
            s['human_pending'] = False
            s['callback_proposed_date'] = ''
            s['callback_proposed_time'] = ''
            s['name_asks'] = 0
            stage = 'locate'
            s['stage'] = stage
            intent = 'other'
        elif s.get('caller_status') == 'third_party' and stage != 'service_wait':
            stage = 'callback'
            s['stage'] = stage
        if stage == 'callback':
            day = callback_day or day
            time_text = callback_time or time_text
        financial_stage = stage in ('negotiate', 'confirm', 'support', 'recorded') and bool(p) and s.get('verified') is True and s.get('caller_status') != 'third_party'
        if financial_stage:
            if amount_reference in ('full', 'floor'):
                resolved = p['past_due'] if amount_reference == 'full' else p['floor']
                if amount:
                    try:
                        if number(amount) != number(resolved):
                            amount = 'conflict'
                    except Exception:
                        amount = 'conflict'
                else:
                    amount = str(resolved)
            elif amount_reference == 'conflict':
                amount = 'conflict'
            if full_unaffordable:
                p['full_too_much'] = True
        proposal = bool(amount or day) and stage in ('negotiate', 'confirm', 'support') and bool(p) and not p.get('recorded') and s.get('caller_status') != 'third_party'
        if question == 'ai':
            prefix = "I am Freya Bank's digital assistant. "
        elif question == 'scam':
            prefix = "You can verify this call by phoning Freya Bank's customer service number. "
        elif question == 'discount':
            prefix = 'I cannot offer a discount or waiver. ' if s.get('verified') and s.get('caller_status') != 'third_party' else 'I can explain what I can help with after the security check. '
        elif question == 'unknown':
            prefix = 'I do not have that information. '
        elif question == 'purpose' and s.get('verified') and s.get('caller_status') != 'third_party':
            prefix = 'I am calling from the collections team about a late payment. '
        if s.get('caller_status') == 'third_party' and question in ('purpose', 'discount', 'unknown'):
            prefix = 'I am a digital assistant calling from Freya Bank, and we are recording this call. '
        if no_talk:
            s['talk_declines'] += 1
        if intent == 'deceased' and (not s.get('verified') or s.get('caller_status') == 'third_party'):
            finish('not_reached', 'deceased', 'I am sorry for your loss.')
        elif intent == 'wrong_number' and (not s.get('verified') or s.get('caller_status') == 'third_party'):
            finish('not_reached', 'wrong_number')
        elif human or (s.get('human_pending') and decision == 'reject'):
            if s['human_offered']:
                s['human_pending'] = False
                transfer('general')
            else:
                s['human_offered'] = True
                s['human_pending'] = True
                s['resume_prompt'] = s.get('prompt', '')
                tell(stage, 'Ask once: May I help you first? Do not require identity verification before an insisted request for a person.')
        elif stage == 'callback' and not s.get('human_pending'):
            callback_turn(day, time_text, decision, intent, newly_third_party)
        elif s['talk_declines'] >= 2:
            finish('no_promise' if s.get('verified') else 'not_verified', 'refused' if s.get('verified') else 'declined')
        elif s.get('human_pending') and decision == 'accept' and not proposal:
            s['human_pending'] = False
            if s.get('caller_status') == 'third_party':
                callback_turn(callback_day or day, callback_time or time_text, 'none', 'other', True)
            else:
                tell(stage, s.get('resume_prompt', 'Ask how you can help, without disclosing account information before verification.'))
        elif s.get('human_pending') and not proposal:
            tell(stage, 'Ask whether you may help first. A question alone is not agreement. If the customer insists on a person, respect the request. Do not disclose account information before verification.')
        elif stage == 'locate':
            if caller == 'name_confirmed' or intent == 'name_yes':
                s['caller_status'] = 'customer_claimed'
                s['security_field'] = 'date_of_birth'
                tell('security', 'Ask only for the customer date of birth. Do not reveal the purpose of the call.')
            elif s['name_asks'] < 2:
                s['name_asks'] += 1
                ordinal = 'This is the second and final identification ask.' if s['name_asks'] == 2 else 'This is the first identification ask to the new speaker.'
                tell('locate', 'After answering any legitimate question, ask exactly: Am I speaking with ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + '? ' + ordinal + ' Do not disclose the purpose.')
            else:
                finish('not_reached', 'unclear')
        elif intent == 'paid' and s.get('verified') and s.get('caller_status') != 'third_party':
            finish('paid', '', 'Payments can take one business day to appear.')
        elif intent == 'dispute' and s.get('verified') and s.get('caller_status') != 'third_party':
            finish('no_promise', 'dispute', 'I understand that you dispute this account.')
        elif stage == 'support' and not proposal and decision in ('accept', 'reject'):
            if decision == 'accept':
                transfer('support')
            else:
                finish('no_promise', 'hardship')
        elif hardship_new and not proposal and s.get('caller_status') != 'third_party':
            if not s.get('hardship'):
                prefix += 'I am sorry you are going through this. '
            s['hardship'] = True
            support()
        elif plan_request and s.get('caller_status') != 'third_party' and not (proposal and (hardship_new or s.get('hardship'))):
            if s.get('hardship'):
                support()
            else:
                transfer('restructuring')
        elif stage == 'security':
            if intent in ('decline_security', 'reject') or ((intent == 'purpose' or question == 'purpose') and not answer and not numeric_dob) or no_talk:
                s['security_declines'] += 1
                if s['security_declines'] >= 2:
                    finish('not_verified', 'declined')
                else:
                    q = 'date of birth' if s['security_field'] == 'date_of_birth' else 'last four digits of the phone number on file'
                    tell('security', 'Explain once that these questions protect the customer account. Then ask for the ' + q + '. Do not disclose the call purpose.')
            elif answer or numeric_dob:
                field = s['security_field']
                good = True
                try:
                    if field == 'date_of_birth':
                        if numeric_dob:
                            bits = re.findall(r'\d+', numeric_dob)
                            if len(bits) != 3 or len(bits[2]) != 4:
                                raise ValueError('need day month year')
                            answer = datetime.date(int(bits[2]), int(bits[1]), int(bits[0])).isoformat()
                        else:
                            answer = datetime.date.fromisoformat(answer).isoformat()
                    else:
                        good = bool(re.fullmatch(r'\d{4}', answer))
                except Exception:
                    good = False
                if good and s['wrong'] < 3 and s.get('caller_status') != 'third_party' and (field == 'date_of_birth' or s.get('dob_pass')):
                    vars['security_field'] = field
                    vars['security_answer'] = answer
                    request('verify')
                else:
                    tell('security', 'Ask for clarification of the same security answer. For a birth date ask for the month as a word and the four-digit year; for the phone ask for exactly the last four digits. This parsing issue does not count as a wrong answer.')
            elif prefix:
                tell('security', s['prompt'])
            else:
                q = 'date of birth' if s['security_field'] == 'date_of_birth' else 'last four digits of the phone number on file'
                tell('security', 'Ask for the ' + q + ', one question only, without revealing the purpose of the call.')
        elif stage == 'service_wait':
            if s.get('caller_status') == 'third_party' and (callback_day or callback_time):
                callback_turn(callback_day, callback_time, decision, intent)
            elif decision == 'accept':
                retry = s.get('retry_kind', '')
                if retry in ('account', 'callback', 'transfer') and not (retry == 'account' and s.get('caller_status') == 'third_party'):
                    request(retry)
                elif s.get('caller_status') == 'third_party':
                    callback_turn('', '', 'none', 'other', True)
                else:
                    transfer('general')
            elif (decision == 'reject' or intent == 'done') and s.get('retry_kind') == 'callback':
                finish('not_reached', 'no_callback', 'No callback was scheduled.')
            elif decision == 'reject' or intent == 'done':
                s['retry_kind'] = ''
                tell('service_wait', 'Acknowledge that the action has not succeeded. Ask whether the customer would like help from a person instead; do not repeat the refused retry or claim success.')
            else:
                tell('service_wait', s['prompt'])
        elif stage == 'recorded':
            if intent == 'change_recorded' or amount or day:
                tell('recorded', 'Say a recorded promise cannot be changed or cancelled during this call. The customer can change it in the mobile app. Ask whether there is another question.')
            elif prefix:
                tell('recorded', 'Answer the legitimate question using only information actually available. Do not change or create another promise. Ask whether there is another question.')
            else:
                finish('promise')
        elif proposal:
            if hardship_new:
                if not s.get('hardship'):
                    prefix += 'I am sorry you are going through this. '
                s['hardship'] = True
            s['human_pending'] = False
            candidate(p, amount, day, too_much=(full_unaffordable and not amount))
        elif stage == 'support':
            if intent in ('done', 'no_talk'):
                finish('no_promise', 'hardship')
            else:
                support()
        elif stage in ('negotiate', 'confirm'):
            if full_unaffordable:
                candidate(p, too_much=True)
            elif decision == 'reject':
                persuade(p)
            elif p.get('need_exact'):
                candidate(p, amount, day)
            elif decision == 'accept':
                if stage == 'confirm' and valid_candidate(p) and p.get('readback') == pair(p['amount'], p['date']):
                    p['confirmed'] = p['readback']
                    create(p)
                else:
                    candidate(p)
            elif prefix:
                tell(stage, s['prompt'])
            else:
                persuade(p)
        else:
            tell(stage, s.get('prompt', 'Ask whether the customer would like help from a person.'))
    if vars.get('next') in ('verify', 'account', 'callback', 'create', 'transfer'):
        s['carry_prefix'] = prefix
    vars['instruction'] = (('First say: ' + prefix + '\n') if prefix else '') + s.get('prompt', vars['instruction'])
except Exception:
    s['pending'] = ''
    s['retry_kind'] = ''
    s['stage'] = 'service_wait'
    s['prompt'] = 'Say you do not have the information needed to continue this action. Do not claim it succeeded. Ask whether the customer would like help from a person. Do not disclose the call purpose to a third party or ask them security questions.'
    vars['instruction'] = s['prompt']
    vars['next'] = 'speak'
vars['call_state'] = json.dumps(s)
for key, empty_value in turn_defaults.items():
    vars[key] = empty_value

speak.task_message:
Current instruction:
{{instruction}}

Supplied date/time anchor: {{now}}.
Customer: {{title}} {{last_name}}.
Authoritative live state: {{call_state}}

The state includes the actual bank product_id, label, type, card_last4, past_due, floor, candidate amount/date, pending readback and stage. The active offer is the help-first question if human_pending is true; otherwise it is the question in the computed instruction for this stage. Speak the requested customer-facing wording naturally without narrating state or code. Ask only the requested question. No tool call is allowed in this turn. Do not add offers, persuasion, financial claims or extra security questions. The opening sentence and prescribed confirmation/text-message wording must be exact. For offers, follow the computed wording: a date-only persuasion instruction refers to the existing payment without re-announcing its unchanged minimum amount or rest-overdue pitch. For final confirmation, always say the computed product, amount and date aloud together and ask exactly 'Do you confirm?'; never shorten this to a date-only check, even when the customer just supplied or accepted that date. Use the exact computed values, not an independently inferred correction. Never say full amount when the computed amount is the floor unless those values are equal. A new customer correction must be processed before being spoken as a new offer. Answer secondary questions using the computed instruction and actual policy or bank facts without undoing the decision or repeating a refused offer. A discount question is not a restructuring request. Do not treat anger, an AI question or scam concern as refusal. A non-answer such as 'You tell me' is not an informational question; use the computed next offer, not the previous one. Do not disclose the purpose to a third party, repeat customer-name identification to a known relative, ask them security questions or negotiate their offer to pay. Arrange contact only; do not ask again for availability already supplied. Actual customer takeover requires fresh name identification and the normal security sequence.

extraction_schema.extraction_prompt:
Latest speech: {{extractor.speech}}
Recent conversation: {{extractor.conversation.last-10}}
{{extractor.type_preamble}}
{{extractor.variables_list}}
Supplied customer: {{title}} {{first_name}} {{last_name}}.
Stored context: {{call_state}}
Extract speaker relationship independently of every topic and question. Explicit spouse/relative identity remains third_party even with a purpose question, an offer to pay or callback availability. Only the latest speech supplies new evidence. Unknown does not erase persistent third-party status. A relative offering to answer questions is not customer takeover. Never infer successful bank verification from speech.

Latest speech: {{extractor.speech}}
Recent conversation: {{extractor.conversation.last-10}}
{{extractor.type_preamble}}
{{extractor.variables_list}}
Only date anchor: {{now}}.
Stored context: {{call_state}}
Extract newly offered callback availability independently of relationship, payment, questions and decisions. Preserve today/tomorrow/this weekday/next weekday for code. Next weekday is the following calendar week. Convert other exact calendar dates to YYYY-MM-DD using supplied now for omitted year. Vague periods stay vague. Choose positively offered availability, not a rejected date mentioned before it. Use conflict for unresolved incompatible proposals. Empty if no new callback date. Never copy an old date or substitute a birth/payment date.

Latest speech: {{extractor.speech}}
Recent conversation: {{extractor.conversation.last-10}}
{{extractor.type_preamble}}
{{extractor.variables_list}}
Only date anchor: supplied now={{now}}.
Stored pending context: {{call_state}}
Extract the positively offered date, not the first date word. 'I cannot pay today' rejects today and yields empty date. 'Not today, but I can pay this Friday' yields this friday. A question about AI must not erase the offered Friday. A date mentioned only as a refused date or hypothetical information question is not a proposal. Consent-only 'yes' adds no date. Copy the positively proposed date words faithfully, without calendar arithmetic or normalization. Keep today, tomorrow, this/next weekday, weekday plus ordinal/cardinal day, ordinary month/day expressions and every explicitly supplied year. For example, Monday the 26th must remain Monday the 26th. Never invent an ISO date, month or year from context: ISO is acceptable only when the customer actually supplied it. Code resolves the copied words against supplied now and checks weekday/day agreement before applying holidays and deadlines. Vague periods such as next week/end of month/salary arrival must remain their original vague words or the sentinel vague, never an invented exact day. If positive proposals conflict without clear correction use conflict, never choose arbitrarily. Never reuse prior-turn values or extract security dates. Keep each clause attached to its product/contact topic; only unambiguous bank product aliases are valid.

